 * 诊断应用服务
 * 协调诊断流程：策略验证 → 代码检索 → LLM分析 → 结果解析 → 审计记录
 */
@Service
public class DiagnosisApplicationService {

    private static final Logger log = LoggerFactory.getLogger(DiagnosisApplicationService.class);

    private static final String SYSTEM_PROMPT = """
        You are an expert software engineering assistant. Given a user query, error information, service name, and relevant code snippets, analyze the problem and produce a structured diagnosis in Chinese.
        Return ONLY a JSON object with this shape:
        {
          "summary": "one-sentence summary of the issue",
          "rootCause": "detailed root cause analysis",
          "suggestions": ["actionable fix 1", "actionable fix 2", ...]
        }
        Do not include markdown fences, explanations, or any text outside the JSON.
        """;

    private final CodeRetriever codeRetriever;
    private final LlmClient llmClient;
    private final DiagnosisAuditor auditor;
    private final PolicyEngine policyEngine;
    private final ObjectMapper objectMapper;

    /**
     * 构造函数
     *
     * @param codeRetriever 代码检索器
     * @param llmClient     LLM 客户端
     * @param auditor       诊断审计器
     * @param policyEngine  策略引擎
     * @param objectMapper  JSON 序列化器
     */
    public DiagnosisApplicationService(CodeRetriever codeRetriever,
                                       LlmClient llmClient,
                                       DiagnosisAuditor auditor,
                                       PolicyEngine policyEngine,
                                       ObjectMapper objectMapper) {
        this.codeRetriever = codeRetriever;
        this.llmClient = llmClient;
        this.auditor = auditor;
        this.policyEngine = policyEngine;
        this.objectMapper = objectMapper;
    }

    /**
     * 执行智能诊断
     *
     * @param request 诊断请求
     * @return 诊断响应
     */
    public DiagnosisResponse diagnose(DiagnosisRequest request) {
        long start = System.currentTimeMillis();
        policyEngine.validate(request);

        List<CodeSnippet> relatedCode = codeRetriever.retrieve(request);
        String userPrompt = buildUserPrompt(request, relatedCode);

        String rawResponse = llmClient.complete(SYSTEM_PROMPT, userPrompt);
        DiagnosisResponse response = parseResponse(rawResponse, relatedCode);

        long duration = System.currentTimeMillis() - start;
        auditor.record(request, response, duration);

        return response;
    }

    /**
     * 构建用户提示词
     * 将诊断请求和相关代码片段组合成完整的提示词
     *
     * @param request  诊断请求
     * @param snippets 相关代码片段列表
     * @return 完整的用户提示词
     */
    private String buildUserPrompt(DiagnosisRequest request, List<CodeSnippet> snippets) {
        StringBuilder builder = new StringBuilder();
        builder.append("Service: ").append(request.service()).append("\n");
        if (request.query() != null && !request.query().isBlank()) {
            builder.append("Query: ").append(request.query()).append("\n");
        }
        if (request.errorInfo() != null && !request.errorInfo().isBlank()) {
            builder.append("Error Info: ").append(request.errorInfo()).append("\n");
        }
        if (!snippets.isEmpty()) {
            builder.append("\nRelevant Code Snippets:\n");
            for (CodeSnippet snippet : snippets) {
                builder.append(snippet.filePath())
                    .append(":").append(snippet.startLine()).append("-").append(snippet.endLine())
                    .append("\n```\n")
                    .append(snippet.content())
                    .append("\n```\n\n");
            }
        }
        return builder.toString().trim();
    }

    /**
     * 解析 LLM 响应
     * 将 LLM 返回的 JSON 字符串解析为 DiagnosisResponse 对象
     *
     * @param rawResponse LLM 原始响应
     * @param relatedCode 相关代码片段列表
     * @return 解析后的诊断响应
     */
    private DiagnosisResponse parseResponse(String rawResponse, List<CodeSnippet> relatedCode) {
        String cleaned = stripMarkdownFences(rawResponse);
        try {
            ParsedLlmResponse parsed = objectMapper.readValue(cleaned, ParsedLlmResponse.class);
            return new DiagnosisResponse(
                parsed.summary,
                parsed.rootCause,
                parsed.suggestions,
                relatedCode
            );
        } catch (JsonProcessingException e) {
            log.warn("Failed to parse LLM response as JSON, using fallback. Response: {}", rawResponse, e);
            return new DiagnosisResponse(
                rawResponse.trim(),
                "",
                List.of(),
                relatedCode
            );
        }
    }

    /**
     * 移除 Markdown 代码块围栏
     *
     * @param text 原始文本
     * @return 移除围栏后的文本
     */
    private String stripMarkdownFences(String text) {
        return text.replaceAll("(?s)^\\s*```(?:json)?\\s*", "")
            .replaceAll("(?s)\\s*```\\s*$", "");
    }

    /**
     * LLM 响应解析结构
     */

/**
 * Git 同步服务
 * 协调仓库同步流程，管理同步状态和事务
 */
@Service
public class GitSyncService {

    private static final Logger log = LoggerFactory.getLogger(GitSyncService.class);

    /**
     * 仓库提供者注册中心
     */
    private final RepositoryProviderRegistry providerRegistry;

    /**
     * 同步状态仓库
     */
    private final RepositorySyncStateRepository syncStateRepository;

    /**
     * 事务模板
     */
    private final TransactionTemplate transactionTemplate;

    /**
     * 创建实例
     *
     * @param providerRegistry      仓库提供者注册中心
     * @param syncStateRepository   同步状态仓库
     * @param transactionManager    事务管理器
     */
    public GitSyncService(RepositoryProviderRegistry providerRegistry,
                          RepositorySyncStateRepository syncStateRepository,
                          PlatformTransactionManager transactionManager) {
        this.providerRegistry = providerRegistry;
        this.syncStateRepository = syncStateRepository;
        this.transactionTemplate = new TransactionTemplate(transactionManager);
    }

    /**
     * 执行仓库同步
     *
     * @param config      仓库配置
     * @param triggerType 触发类型
     * @param triggeredBy 触发者
     * @return 同步状态实体
     */
    public RepositorySyncStateEntity sync(RepositoryConfigEntity config, TriggerType triggerType, String triggeredBy) {
        String stateId = transactionTemplate.execute(status -> createState(config, triggerType, triggeredBy));

        try {
            log.info("Starting sync for repository {} (trigger: {})", config.getName(), triggerType);
            var provider = providerRegistry.getProvider(config.getType());
            RepositorySyncResult result = provider.sync(config);

            log.info("Successfully synced repository {} to commit {} ({} changed files)",
                config.getName(), result.latestCommit(), result.changedFiles().size());

            return transactionTemplate.execute(status -> markSuccess(stateId, result));
        } catch (Exception e) {
            log.error("Failed to sync repository {}", config.getName(), e);
            return transactionTemplate.execute(status -> markFailed(stateId, e));
        }
    }

    /**
     * 创建同步状态记录
     *
     * @param config      仓库配置
     * @param triggerType 触发类型
     * @param triggeredBy 触发者
     * @return 状态 ID
     */
    private String createState(RepositoryConfigEntity config, TriggerType triggerType, String triggeredBy) {
        String stateId = UUID.randomUUID().toString();
        RepositorySyncStateEntity state = new RepositorySyncStateEntity();
        state.setId(stateId);
        state.setRepository(config);
        state.setStatus(SyncStatus.SYNCING);
        state.setTriggerType(triggerType);
        state.setTriggeredBy(triggeredBy);
        state.setStartedAt(Instant.now());
        state.setCreatedAt(Instant.now());
        syncStateRepository.save(state);
        return stateId;
    }

    /**
     * 标记同步成功
     *
     * @param stateId 状态 ID
     * @param result  同步结果
     * @return 更新后的同步状态实体
     */
    private RepositorySyncStateEntity markSuccess(String stateId, RepositorySyncResult result) {
        RepositorySyncStateEntity state = syncStateRepository.findById(stateId)
            .orElseThrow(() -> new IllegalStateException("Sync state not found: " + stateId));
        state.setStatus(SyncStatus.SUCCESS);
        state.setLatestCommit(result.latestCommit());
        state.setPreviousCommit(result.previousCommit());
        state.setChangedFiles(result.changedFiles().size());
        state.setCompletedAt(Instant.now());
        return syncStateRepository.save(state);
    }

    /**
     * 标记同步失败
     *
     * @param stateId 状态 ID
     * @param e       异常
     * @return 更新后的同步状态实体
     */

/**
 * 仓库初始化器
 * 在应用启动时执行仓库初始同步
 */
@Component
public class RepositoryInitializer implements ApplicationRunner {

    private static final Logger log = LoggerFactory.getLogger(RepositoryInitializer.class);

    /**
     * 是否启用初始同步
     */
    @Value("${repository.initial-sync.enabled:false}")
    private boolean enabled;

    /**
     * 仓库配置仓库
     */
    private final RepositoryConfigRepository configRepository;

    /**
     * Git 同步服务
     */
    private final GitSyncService gitSyncService;

    /**
     * 创建实例
     *
     * @param configRepository 仓库配置仓库
     * @param gitSyncService   Git 同步服务
     */
    public RepositoryInitializer(RepositoryConfigRepository configRepository,
                                 GitSyncService gitSyncService) {
        this.configRepository = configRepository;
        this.gitSyncService = gitSyncService;
    }

    @Override
    public void run(ApplicationArguments args) {
        if (!enabled) {
            log.info("Repository initial sync is disabled");
            return;
        }

        var configs = configRepository.findByEnabledTrue();
        if (configs.isEmpty()) {
            log.info("No enabled repository configurations found, skipping initial sync");
            return;
        }

        log.info("Starting initial sync for {} repositories", configs.size());

        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (var config : configs) {
                executor.submit(() -> syncSafely(config));
            }
        }

        log.info("Initial sync submissions completed");
    }

